import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
try {
  const response = await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 })
  if (!response?.ok()) throw new Error(`Load failed: ${response?.status()}`)
  await page.waitForFunction(() => window.__wandlore && document.getElementById('start-btn'))
  await page.locator('#start-btn').click()
  await page.waitForFunction(() => !document.getElementById('start-screen')?.classList.contains('fade') === false || document.getElementById('hud')?.classList.contains('hidden') === false, null, { timeout: 10000 }).catch(() => {})
  await page.waitForTimeout(1000)
  const started = await page.evaluate(() => ({ started: !!window.__wandlore.state.flags.started, hudHidden: document.getElementById('hud').classList.contains('hidden') }))
  const entered = await page.evaluate(() => window.__wandlore.beginDuel('elara'))
  if (!entered || !(await page.locator('#duel-ui').isVisible())) throw new Error('Duel failed to enter')
  await page.waitForTimeout(1800)
  await page.evaluate(() => {
    const { duel } = window.__wandlore
    duel.tryCast(0)
    duel.damageEnemy(99999, null, { passive: true })
  })
  await page.waitForFunction(() => !document.getElementById('result-root').classList.contains('hidden'), { timeout: 10000 })
  const resultTitle = await page.locator('.result-title').innerText()
  const outcome = await page.locator('.result-sub').innerText()
  if (resultTitle !== 'VICTORY') throw new Error(`Unexpected result: ${resultTitle}`)
  await page.locator('[data-result="close"]').click()
  await page.waitForFunction(() => document.getElementById('result-root').classList.contains('hidden') && !document.body.classList.contains('in-duel') && document.getElementById('duel-ui').classList.contains('hidden'), { timeout: 10000 })
  await page.waitForTimeout(800)
  await page.screenshot({ path: '/tmp/shots/36-final.jpg', type: 'jpeg', quality: 72 })
  const final = await page.evaluate(() => ({ inDuel: document.body.classList.contains('in-duel'), resultHidden: document.getElementById('result-root').classList.contains('hidden'), duelUiHidden: document.getElementById('duel-ui').classList.contains('hidden'), arena: window.__wandlore.world.duelArena }))
  console.log(JSON.stringify({ started, entered, resultTitle, outcome, final, errors }, null, 2))
  if (errors.length) process.exitCode = 1
} finally {
  await browser.close()
}
EOF

