@media (max-height:700px){
  .wand-stage{height:230px}
  .panel-head{padding:12px 22px 10px}
  .panel-body{padding:14px 22px 18px}
}

/* ============================================================
   TOUCH CONTROLS
   ============================================================ */
#touch-ui{display:none;position:absolute;inset:0;pointer-events:none;z-index:12}
#touch-ui.on{display:block}
#joystick{position:absolute;left:max(16px,env(safe-area-inset-left));bottom:max(18px,env(safe-area-inset-bottom));width:132px;height:132px;border-radius:50%;pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;background:radial-gradient(circle at 50% 42%,rgba(44,32,74,.55),rgba(10,8,18,.62) 72%);border:1px solid rgba(217,185,120,.3);box-shadow:inset 0 0 30px rgba(0,0,0,.55),0 10px 26px rgba(0,0,0,.4)}
.joy-ring{position:absolute;inset:15px;border-radius:50%;border:1px dashed rgba(217,185,120,.2);pointer-events:none}
.joy-tick{position:absolute;font-size:8px;line-height:1;color:rgba(217,185,120,.42);pointer-events:none}
.joy-up{top:6px;left:50%;transform:translateX(-50%)}
.joy-down{bottom:6px;left:50%;transform:translateX(-50%)}
.joy-left{left:7px;top:50%;transform:translateY(-50%)}
.joy-right{right:7px;top:50%;transform:translateY(-50%)}
#joy-thumb{position:absolute;left:50%;top:50%;width:58px;height:58px;margin:0;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none;background:radial-gradient(circle at 38% 30%,#7761ad,#2b2148 72%);border:1px solid rgba(217,185,120,.55);box-shadow:0 0 22px rgba(154,123,224,.4),inset 0 0 14px rgba(255,255,255,.1)}
#touch-buttons{position:absolute;right:max(14px,env(safe-area-inset-right));bottom:max(16px,env(safe-area-inset-bottom));display:flex;gap:8px;align-items:flex-end;pointer-events:none}
.touch-btn{pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;width:58px;height:58px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font-family:"Cinzel",serif;font-size:19px;line-height:1;color:#f0e2c2;background:radial-gradient(circle at 40% 30%,rgba(52,38,86,.94),rgba(12,9,22,.94));border:1px solid rgba(217,185,120,.36);box-shadow:0 8px 20px rgba(0,0,0,.5),inset 0 0 12px rgba(255,255,255,.04);transition:transform .1s,border-color .15s,opacity .15s,box-shadow .15s}
.touch-btn small{font-size:7px;letter-spacing:.1em;text-transform:uppercase;color:rgba(217,185,120,.78);font-family:"Cinzel",serif}
.touch-btn.pressed,.touch-btn:active{transform:scale(.92);border-color:var(--gold);background:radial-gradient(circle at 40% 30%,rgba(94,70,146,.96),rgba(24,18,40,.96))}
#touch-shield{color:#9fd0ff}
#touch-dodge{color:#c9a6ff;font-size:25px}
#touch-interact{font-size:15px;color:var(--gold-bright);opacity:.32}
#touch-interact.ready{opacity:1;border-color:rgba(217,185,120,.75);box-shadow:0 0 22px rgba(217,185,120,.35),0 8px 20px rgba(0,0,0,.5);animation:touchPulse 1.7s ease-in-out infinite}
@keyframes touchPulse{50%{box-shadow:0 0 30px rgba(217,185,120,.55),0 8px 20px rgba(0,0,0,.5)}}

/* compact HUD + thumb-friendly layout when a touch pointer is present */
body.touch .hud-left{top:8px;left:8px;transform:scale(.78);transform-origin:top left}
body.touch .hud-right{top:8px;right:8px}
body.touch .hud-buttons{display:grid;grid-template-columns:repeat(3,42px);gap:5px}
body.touch .hud-btn{width:42px;height:38px;padding:0;display:grid;place-items:center;justify-items:center;font-size:17px}
body.touch .hud-btn span:not(.hb-icon){display:none}
body.touch .hud-btn kbd{display:none}
body.touch .equipped-wand{display:none}
body.touch #minimap-wrap{left:max(12px,env(safe-area-inset-left));top:76px;bottom:auto;transform:scale(.6);transform-origin:top left}
body.touch.in-duel #minimap-wrap{display:none}
body.touch.in-duel .hud-right{display:none}
body.touch.in-duel .hud-left{opacity:.22}

body.touch #hotbar-wrap{left:auto;right:max(12px,env(safe-area-inset-right));bottom:calc(max(16px,env(safe-area-inset-bottom)) + 70px);transform:none;align-items:flex-end;gap:5px}
body.touch #hotbar{display:grid;grid-template-columns:repeat(2,54px);gap:8px}
body.touch .spell-slot{width:54px;height:54px;border-radius:13px}
body.touch .spell-slot .s-name{display:none}
body.touch .spell-slot .s-icon{font-size:20px;margin-top:0}
body.touch .hotbar-hint{display:none}
body.touch .mana-row{width:116px}

body.touch #interact-prompt{bottom:calc(max(16px,env(safe-area-inset-bottom)) + 84px);left:50%;padding:10px 18px 10px 10px;font-size:16px}
body.touch #toasts{left:12px;right:auto;bottom:calc(max(16px,env(safe-area-inset-bottom)) + 150px);align-items:flex-start;max-width:calc(100vw - 190px)}
body.touch .toast{max-width:100%;font-size:13px;padding:8px 12px}
body.touch #objective-toast{top:64px;max-width:70vw;font-size:11px}
body.touch #sound-toggle{right:auto;left:12px;bottom:calc(max(16px,env(safe-area-inset-bottom)) + 150px);width:36px;height:36px}

body.touch .panel-close{width:40px;height:40px}
body.touch .dlg-opt{padding:10px 16px;font-size:15px}
body.touch #dialogue{width:calc(100vw - 24px);padding:16px 16px 14px}
body.touch .rune-btn{width:58px;height:58px}

body.touch .duel-enemy{top:78px}
body.touch .duel-player{top:132px}
body.touch .duel-center-msg{font-size:30px}

/* backdrop blur over a live WebGL canvas is costly on mobile GPUs */
body.touch .player-card,body.touch .pill,body.touch #quest-tracker,body.touch .equipped-wand,
body.touch .toast,body.touch #dialogue,body.touch .panel,body.touch .panel-backdrop,
body.touch .result-card,body.touch .lesson-card,body.touch #sound-toggle{backdrop-filter:none!important}
body.touch #vignette{box-shadow:inset 0 0 90px rgba(3,2,8,.78)}
body.touch #joystick,body.touch .touch-btn{backdrop-filter:none!important}

/* start screen hint swap */
.start-controls-touch{display:none}
body.touch .start-controls-keys{display:none}
body.touch .start-controls-touch{display:flex;gap:10px 16px}

@media (max-height:520px) and (pointer:coarse){
  #joystick{width:110px;height:110px;bottom:12px;left:12px}
  #joy-thumb{width:50px;height:50px}
  .touch-btn{width:52px;height:52px;font-size:17px}
  #touch-buttons{bottom:12px;right:12px;gap:6px}
  body.touch #hotbar-wrap{bottom:calc(max(12px,env(safe-area-inset-bottom)) + 60px)}
  body.touch #hotbar{grid-template-columns:repeat(2,48px);gap:6px}
  body.touch .spell-slot{width:48px;height:48px}
  body.touch .mana-row{width:102px}
  body.touch .duel-enemy{top:50px;width:240px}
  body.touch .duel-player{top:104px}
}

