let touchUiOn = false
function updateTouchUI() {
  if (!touchMode) return
  const on = touchAllowed()
  if (on === touchUiOn) return
  touchUiOn = on
  $('touch-ui').classList.toggle('on', on)
  if (!on) {
    resetJoystick()
    touchShield = false
    $('touch-shield').classList.remove('pressed')
  }
}

